  "livan-8-2025-precio-ficha-tecnica": { lanzamiento: 2024, hitos: [ { anio: 2024, tipo: "lanzamiento", cambio: "En noviembre arranca la producción del Livan 8 y el día 22 se presenta en Yakarta su versión con volante a la derecha. Mantiene la base del Maple 80V, frontal cerrado de eléctrico, distribución 2+2+3 y dos baterías: 50,4 kWh LFP con 407 km CLTC y 68,03 kWh con 515 km CLTC.", foto: null }, { anio: 2021, tipo: "lanzamiento", cambio: "El antecedente directo sale de la línea de Chongqing en mayo: el Maple 80V, un monovolumen eléctrico pensado para plataformas de movilidad, con batería intercambiable en unos 60 segundos y silueta derivada del Geely Jiaji, que anticipa la fórmula que luego heredará el Livan 8.", foto: null }, { anio: 2022, tipo: "restyling", cambio: "El 24 de enero Geely y Lifan completan el registro de su empresa conjunta al 50 %, bautizada Livan —Ruilan en China—, con capital de 600 millones de yuanes y un ecosistema propio de intercambio de baterías como eje de toda su gama eléctrica posterior.", foto: null } ] },
  "livan-9-2024-precio-ficha-tecnica": { lanzamiento: 2022, hitos: [{ anio: 2022, tipo: "lanzamiento", cambio: null, foto: null }] },
  "livan-maple-60s-2024-precio-ficha-tecnica": { lanzamiento: 2021, hitos: [{ anio: 2021, tipo: "lanzamiento", cambio: null, foto: null }] },
  "livan-maple-80v-2024-precio-ficha-tecnica": { lanzamiento: 2020, hitos: [ { anio: 2020, tipo: "lanzamiento", cambio: null, foto: null }, { anio: 2022, tipo: "lanzamiento", cambio: "Livan Automotive nace en enero de 2022 como empresa conjunta entre Geely y Lifan Technology, creada específicamente para eléctricos de batería intercambiable. Maple, hasta entonces marca propia de Geely, queda integrada en la nueva estructura y su nombre pasa a identificar modelos concretos, entre ellos este monovolumen 80V.", foto: null }, { anio: 2022, tipo: "lanzamiento", cambio: "En junio de 2022 el Maple 80V PRO se exhibe en el Salón de Chongqing junto al Livan 9, dentro de la ofensiva de Livan en el intercambio de baterías. La propuesta no busca al particular europeo, sino a flotas y servicios de movilidad en China, con cambio de batería en unos 60 segundos.", foto: null }, { anio: 2024, tipo: "restyling", cambio: "La configuración de 2024 que recoge esta ficha conserva 136 CV, 230 Nm de par y tracción delantera, con batería de 52,56 kWh y 410 km de autonomía en ciclo CLTC chino. Mantiene seis plazas y 4.706 mm de longitud, sin que Livan llegase a comercializarlo en España ni en Europa.", foto: null } ] },
