  "opel-vivaro-electrico-2025-precio-ficha-tecnica": { lanzamiento: 2019, hitos: [ { anio: 2019, tipo: "lanzamiento", cambio: "Tercera generación con tres longitudes de carrocería —4,60, 4,95 y 5,30 metros—, carga útil de hasta 1.400 kilos y capacidad de remolque de hasta 2.500 kilos según Stellantis. Suma sistemas como la cámara trasera panorámica de 180 grados y el sistema de carga FlexCargo para objetos largos.", foto: null }, { anio: 2001, tipo: "lanzamiento", cambio: "Opel estrena el Vivaro como comercial ligero en versiones furgoneta panelada, de transporte de personas y plataforma cabina. Esta primera etapa se prolonga hasta 2014 y, según Stellantis, supera las 650.000 unidades vendidas, una base que explica por qué el nombre sobrevivió a dos relevos generacionales completos.", foto: null }, { anio: 2014, tipo: "restyling", cambio: "Llega la segunda generación y el Vivaro sigue apoyándose en formatos pensados para carga y pasajeros, sin versión eléctrica de batería en esta etapa. Su relevo llegaría solo cinco años después, ya bajo una nueva arquitectura de grupo que sí permitiría electrificar la furgoneta mediana de Opel.", foto: null }, { anio: 2020, tipo: "restyling", cambio: "Debuta el Vivaro-e sobre la plataforma EMP2, capaz de combinar motores de combustión y eléctricos. Opel lo anuncia con dos baterías, 50 kWh para hasta 200 kilómetros WLTP y 75 kWh para hasta 300, pensando expresamente en repartos de última milla y en entrar en zonas urbanas de bajas emisiones.", foto: null }, { anio: 2023, tipo: "restyling", cambio: "Opel presenta el Vivaro renovado con frontal Vizor por primera vez en un comercial de la marca, doble pantalla de 10 pulgadas y la denominación Vivaro Electric. La batería de 50 kWh carga en continua a 100 kW y suma la toma e-PTO para alimentar equipos externos sin generador.", foto: null } ] },
