  "dongfeng-vigo-electrico-precio-espana-ficha": { lanzamiento: 2026, hitos: [ { anio: 2026, tipo: "lanzamiento", cambio: "En septiembre de 2026 Dongfeng presentó el Vigo en su primer Dongfeng Day en Madrid y abrió pedidos en España junto al Mage PHEV. Llegó con un solo acabado, motor de 163 CV y PVP de 29.990 euros, ampliando una gama que en España había arrancado con el urbano Box.", foto: "/media/historia-dongfeng-vigo-electrico-precio-espana-ficha-2026.webp" }, { anio: 2025, tipo: "lanzamiento", cambio: "Dongfeng desveló las primeras imágenes del Nammi 06 el 21 de febrero de 2025 y lo presentó el 8 de abril, antes de su debut público en el Salón de Shanghái. Nació como el hermano mayor del Nammi 01, sobre la arquitectura Quantum S3, pensado para competir con el BYD Yuan Up.", foto: null }, { anio: 2025, tipo: "lanzamiento", cambio: "Las preventas se abrieron el 28 de abril de 2025 en Shanghái y las primeras entregas en China comenzaron el 27 de mayo. En su mercado de origen se ofreció con dos baterías LFP, de 44,94 y 51,87 kWh, una segunda opción que es la única que ha llegado a España como Vigo.", foto: null } ] },
  "dongfeng-mage-phev-precio-espana-ficha": { lanzamiento: 2026, hitos: [ { anio: 2026, tipo: "lanzamiento", cambio: "En septiembre de 2026 Dongfeng España presentó el Mage PHEV junto al Vigo eléctrico en su primer Dongfeng Day en Madrid. Es el primer híbrido enchufable de la marca en España, con 299 CV, batería de 17 kWh, 89 km eléctricos WLTC y un único acabado.", foto: "/media/historia-dongfeng-mage-phev-precio-espana-ficha-2026.webp" }, { anio: 2023, tipo: "lanzamiento", cambio: "El 9 de julio de 2023 Dongfeng Aeolus lanzó en China el Haohan, el modelo que fuera de su mercado de origen se conoce como Mage. Fue presentado como primer paso de la transformación de nueva energía de Aeolus, con tecnología híbrida Mach DH-i y versiones híbrida y enchufable.", foto: null } ] },
