  "nissan-primastar-combi-dci-2026-precio-ficha-tecnica": { lanzamiento: 2021, hitos: [ { anio: 2021, tipo: "lanzamiento", cambio: "A finales de 2021 Nissan reorganiza sus comerciales y la NV300 actualizada recupera el nombre Primastar. Estrena frontal, interior renovado y el 2.0 dCi en varias potencias. Es la generación de esta ficha, gemela de la Trafic, que ya no se fabrica en Barcelona sino en Francia.", foto: null }, { anio: 2001, tipo: "lanzamiento", cambio: "La primera Primastar nace como proyecto X83 de la Alianza: misma furgoneta que la Renault Trafic y la Opel Vivaro, con producción en la planta Nissan de la Zona Franca de Barcelona. Aquella generación se mantiene en catálogo hasta 2014, muy extendida en España como combi, furgón y base camper.", foto: null }, { anio: 2016, tipo: "restyling", cambio: "Presentada en el Salón de Hannover, la NV300 toma el relevo de la Primastar y deja atrás el nombre durante cinco años. Se fabrica en Sandouville, en Francia, ya sobre la base de la Trafic de tercera generación, con carrocerías de carga, mixta y combi de hasta nueve plazas.", foto: null }, { anio: 2025, tipo: "restyling", cambio: "Euro NCAP reevalúa la gama de comerciales con el nuevo sistema de estrellas que sustituye a las medallas y la Primastar obtiene cuatro, con un 68 % en conducción segura, un 61 % en prevención y un 80 % tras el accidente. Venía de ser Plata en 2023 y Oro en 2024.", foto: null } ] },
  "nissan-leaf-e-plus-62kwh-2023-precio-ficha-tecnica": { lanzamiento: 2017, hitos: [{ anio: 2017, tipo: "lanzamiento", cambio: null, foto: null }, { anio: 2022, tipo: "restyling", cambio: "restyling/facelift de mitad de ciclo", foto: null }, { anio: 2025, tipo: "fin", cambio: null, foto: null }] },
  "nissan-ariya-63kwh-218-2025-precio-ficha-tecnica": { lanzamiento: 2022, hitos: [{ anio: 2022, tipo: "lanzamiento", cambio: null, foto: null }, { anio: 2026, tipo: "restyling", cambio: "restyling/facelift de mitad de ciclo", foto: null }] },
  "nissan-ariya-e4orce-306-2025-precio-ficha-tecnica": { lanzamiento: 2022, hitos: [{ anio: 2022, tipo: "lanzamiento", cambio: null, foto: null }, { anio: 2026, tipo: "restyling", cambio: "restyling/facelift de mitad de ciclo", foto: null }] },
  "nissan-ariya-nismo-435-2025-precio-ficha-tecnica": { lanzamiento: 2022, hitos: [{ anio: 2022, tipo: "lanzamiento", cambio: null, foto: null }, { anio: 2026, tipo: "restyling", cambio: "restyling/facelift de mitad de ciclo", foto: null }] },
  "nissan-micra-ev-40kwh-2026-precio-ficha-tecnica": { lanzamiento: 2025, hitos: [{ anio: 2025, tipo: "lanzamiento", cambio: null, foto: null }] },
  "nissan-townstar-evalia-ev-2026-precio-ficha-tecnica": { lanzamiento: 2021, hitos: [{ anio: 2021, tipo: "lanzamiento", cambio: null, foto: null }] },
  "nissan-primastar-combi-dci170-2026-precio-ficha-tecnica": { lanzamiento: 2021, hitos: [ { anio: 2021, tipo: "lanzamiento", cambio: "El 27 de septiembre de 2021 Nissan reorganiza su gama de comerciales y recupera los nombres históricos: la NV400 pasa a Interstar y la NV300 vuelve a llamarse Primastar. No fue solo un cambio de emblema: la furgoneta basada en la Trafic estrenó frontal con parrilla nueva, ópticas LED y motores diésel adaptados a la normativa Euro 6d.", foto: null }, { anio: 2001, tipo: "lanzamiento", cambio: "Nissan estrena el nombre Primastar para su versión de la segunda generación de la Renault Trafic, compartida también con la Opel Vivaro. La fórmula era la de la Alianza: misma furgoneta mediana francesa con emblemas distintos, en versiones de carga y de pasajeros que se mantendría en catálogo hasta bien entrada la década siguiente.", foto: null }, { anio: 2016, tipo: "restyling", cambio: "Presentada en el Salón de Hannover, la NV300 sustituye a la Primastar y jubila temporalmente el nombre. Se fabricaba en Sandouville, en Francia, compartiendo plataforma y componentes con la Renault Trafic, la Opel Vivaro y la Fiat Talento, y ofrecía carrocería Combi de hasta nueve plazas con motores 1.6 dCi de entre 95 y 145 CV.", foto: null }, { anio: 2025, tipo: "restyling", cambio: "Euro NCAP sustituye las medallas de sus valoraciones de furgonetas por estrellas y reevalúa la gama Nissan: la Primastar obtiene cuatro, con un 68 % en conducción segura, un 61 % en evitación de colisiones y un 80 % en seguridad tras el accidente. El organismo la describió como una buena elección para quien busca un comercial seguro.", foto: null } ] },
  "onvo-l60-2026-precio-ficha-tecnica": { lanzamiento: 2024, hitos: [ { anio: 2024, tipo: "lanzamiento", cambio: "Onvo se presentó el 15 de mayo de 2024 como la marca de volumen de NIO y el L60 fue su primer modelo, un SUV coupé mediano sobre la plataforma NT3.0 de 900 V pensado directamente contra el Tesla Model Y. Salió a la venta el 19 de septiembre y las entregas empezaron el 28 de ese mes.", foto: null }, { anio: 2025, tipo: "restyling", cambio: "El 19 de septiembre de 2025 llegó una primera puesta al día con los precios sin cambios: llantas y colores nuevos, bandeja trasera para los pasajeros y un consumo rebajado hasta 11,9 kWh/100 km en la versión de tracción trasera. Onvo habló de más de 30 mejoras y las entregas de esta serie empezaron a finales de octubre.", foto: null }, { anio: 2026, tipo: "restyling", cambio: "El 11 de junio de 2026 se lanzó la actualización que define a esta ficha: precio de salida rebajado a 192.800 yuanes, 106 mejoras declaradas y versiones Max+ y Ultra+ con LiDAR y el chip propio Shenji NX9031. El Pro mantuvo la conducción asistida por cámaras con un Nvidia Orin-X y las entregas comenzaron al día siguiente.", foto: null } ] },
