  "volkswagen-golf-variant-15-etsi-2026-precio-ficha-tecnica": { lanzamiento: 2019, hitos: [{ anio: 2019, tipo: "lanzamiento", cambio: null, foto: null }, { anio: 2024, tipo: "restyling", cambio: "restyling/facelift de mitad de ciclo", foto: null }] },
  "volkswagen-golf-gte-2026-precio-ficha-tecnica": { lanzamiento: 2019, hitos: [ { anio: 2019, tipo: "lanzamiento", cambio: null, foto: null }, { anio: 2024, tipo: "restyling", cambio: "restyling/facelift de mitad de ciclo", foto: null }, { anio: 2014, tipo: "lanzamiento", cambio: "Volkswagen lo presentó en el Salón de Ginebra como su primer híbrido enchufable y hermano eléctrico del GTI y del GTD. Combinaba un 1.4 TSI de 150 CV con un motor eléctrico de 102 CV para 204 CV y 350 Nm conjuntos, batería de 8,8 kWh y unos 50 km en modo eléctrico.", foto: null }, { anio: 2020, tipo: "restyling", cambio: "Con el Golf VIII el GTE subió a 245 CV y 400 Nm manteniendo el 1.4 TSI, pero estrenó una batería de 13 kWh, un 50 % mayor que la anterior. Volkswagen homologó hasta 64 km eléctricos en ciclo WLTP y lo puso a la venta junto al eHybrid de 204 CV, más tranquilo.", foto: null } ] },
