  "cupra-terramar-20-tsi-204-2026-precio-ficha-tecnica": { lanzamiento: 2024, hitos: [{ anio: 2024, tipo: "lanzamiento", cambio: null, foto: null }] },
  "cupra-formentor-20-tdi-2026-precio-ficha-tecnica": { lanzamiento: 2020, hitos: [ { anio: 2020, tipo: "lanzamiento", cambio: "Presentado en marzo de 2020, el Formentor fue el primer modelo diseñado y desarrollado en exclusiva para CUPRA, sin un gemelo equivalente en SEAT. Se fabrica en Martorell y tomó el nombre del cabo mallorquín de Formentor, cuyas rocas inspiraron los marcados pliegues laterales de la carrocería.", foto: null }, { anio: 2024, tipo: "restyling", cambio: "restyling/facelift", foto: null }, { anio: 2021, tipo: "restyling", cambio: "En febrero de 2021 CUPRA celebró su tercer aniversario con el VZ5, equipado con el motor 2.5 TSI de cinco cilindros de 390 CV y 480 Nm, tracción 4Drive y una aceleración de 0 a 100 km/h en 4,2 segundos. Su producción se limitó a 7.000 unidades para todo el mundo.", foto: null }, { anio: 2025, tipo: "restyling", cambio: "En noviembre de 2025 Euro NCAP reevaluó el Formentor renovado con su protocolo más exigente y le mantuvo las cinco estrellas, con un 91 % en protección de ocupantes adultos y un 86 % en infantil. La misma nota máxima ya la había logrado el modelo original en las pruebas de 2021.", foto: null } ] },
  "cupra-formentor-20-tsi-204-2026-precio-ficha-tecnica": { lanzamiento: 2020, hitos: [{ anio: 2020, tipo: "lanzamiento", cambio: null, foto: null }, { anio: 2024, tipo: "restyling", cambio: "restyling/facelift", foto: null }] },
  "cupra-leon-sportstourer-20-tdi-2026-precio-ficha-tecnica": { lanzamiento: 2020, hitos: [ { anio: 2020, tipo: "lanzamiento", cambio: "El primer Cupra León se presentó el 20 de febrero de 2020, ya como marca independiente de SEAT, con dos carrocerías: cinco puertas y familiar Sportstourer. Su estreno público en el Salón de Ginebra de 2020 se canceló por la pandemia de COVID-19.", foto: null }, { anio: 2024, tipo: "restyling", cambio: "restyling/facelift", foto: null }, { anio: 2025, tipo: "restyling", cambio: "En febrero de 2025, según km77, el motor diésel de 150 CV con cambio DSG se incorporó a la gama del León renovado, manteniendo la carrocería Sportstourer como la opción familiar diésel del modelo.", foto: null }, { anio: 2025, tipo: "restyling", cambio: "En noviembre de 2025 Euro NCAP reevaluó el Cupra León renovado con su protocolo más exigente y le confirmó las cinco estrellas, con un 88 % en protección de ocupantes adultos, un 86 % en infantil, un 82 % en usuarios vulnerables y un 77 % en asistentes de seguridad.", foto: null } ] },
